var VAUtils = Class.create();
VAUtils.prototype = {
    initialize: function() {
    },

	/* similar validation we do in attachments_util.js for platform and portal */
	validateAttachment: function(file, field) {
		if (field.allowedFileSize) {
			var attrMaxSize = parseInt(field.allowedFileSize);
			var allowedSizeInBytes = attrMaxSize * 1048576; // 1048576 -> MB_TO_BYTES
			if (file.size > allowedSizeInBytes)
				return { type : 'failure', message: gs.getMessage('The size of the uploaded file cannot exceed {0} MB', field.allowedFileSize) };
		}
		if (Array.isArray(field.allowedExtensions) && field.allowedExtensions.length) {
			var dot = file.name.lastIndexOf('.') + 1;
			var suffix = file.name.substring(dot).toLowerCase();
			for (var i = 0; i < field.allowedExtensions.length; i++) {
				if (suffix === field.allowedExtensions[i].toLowerCase())
					return { type : 'success' };
			}
			return { type : 'failure', message: gs.getMessage('The uploaded file type is not permitted; allowed types are {0}', field.allowedExtensions.toString()) };
		}
		return { type : 'success' };
	},

	isValidEmail: function(email) {
		var regex = new RegExp("([a-zA-Z0-9_\\-\\.]+)@([a-zA-Z0-9_\\-\\.]+)\.([a-zA-Z]{2,5})");
		return regex.test(email);
	},


	isValidURL: function(url) {
		var regex = new RegExp("(((ftp|http|https):\/\/)|(www\.))([-\w\.\/#$\?=+@&%_:;]+)");
		return regex.test(url);
	},


	isValidIPAddress: function(ip) {
		return (SncIPAddressV4.get(ip) || SncIPAddressV6.get(ip));
	},

    type: 'VAUtils'
};

var PwdAjaxPublicEnrollEmail = Class.create();
PwdAjaxPublicEnrollEmail.prototype = Object.extendsObject(PwdAjaxEnrollEmail, {

	// Let's make this one public.
	isPublic : function() {
		return true;
	},

	// return details of a users subscription
	// or email address from his/her profile
	getEmailVerificationInfo:function() {
		// check the security before anything else.
		// If any violation is found, then just return.

		if (!this._validateSecurity())
			return;

		// call the method in the parent.
		this.getVerificationInfo();
	},

	type: 'PwdAjaxPublicEnrollEmail'
});

var AutoResolutionSLACondition = Class.create();
AutoResolutionSLACondition.prototype = Object.extendsObject(SLAConditionBase, {

	cancel: function() {
		this.lu.logInfo('AutoResolutionSLACondition.cancel called');
		if (SLAConditionBase.prototype.cancel.call(this)) {
			//If cancel condition matches, set IAR context to inactive. 
			this._markContextInactive(AutoResolutionConstants.SLA_STATE.CANCELED);
			return true;
		}
		return false;
	},

	complete: function() {
		this.lu.logInfo('AutoResolutionSLACondition.complete called');
		if (SLAConditionBase.prototype.complete.call(this)) {
			//If complete condition matches, set IAR context to inactive. 
			this._markContextInactive(AutoResolutionConstants.SLA_STATE.COMPLETED);
			return true;
		}
		return false;		
	},

	_markContextInactive: function(contextSLAState) {
		var contextGr = new GlideRecord(AutoResolutionConstants.CONTEXT_TABLE_NAME);
			contextGr.addActiveQuery();
			contextGr.addQuery(AutoResolutionConstants.CONTEXT_TASK_SLA_FIELD_NAME, this.taskSLA.getUniqueValue());
			contextGr.query();
			contextGr.next();
			if(contextGr.isValidRecord()) {
				contextGr.setValue(AutoResolutionConstants.ACTIVE_FIELD_NAME, false);
				contextGr.setValue(AutoResolutionConstants.CONTEXT_SLA_STATE_FIELD_NAME , contextSLAState);
				contextGr.update();
			}
	},

    type: 'AutoResolutionSLACondition'
});
